import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int restart = 0;
        int drain = 0;
        for (int i = 0; i < n; i++) {
            String state = sc.next();
            int liveness = state.equals("deadlock") ? 500 : 200;
            int readiness = state.equals("ready") ? 200 : 503;
            if (liveness == 500) restart++;
            if (readiness == 503) drain++;
            System.out.println("liveness=" + liveness + " readiness=" + readiness);
        }
        System.out.println("restart=" + restart + " drain=" + drain);
    }
}

