import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Set<String> seen = new HashSet<>();
        boolean bad = false;
        for (int i = 0; i < n; i++) {
            String key = sc.next();
            int value = sc.nextInt();
            seen.add(key);
            String result;
            switch (key) {
                case "timeout" -> result = value >= 1 && value <= 30000 ? "OK" : "OUT_OF_RANGE";
                case "poolSize" -> result = value >= 1 && value <= 100 ? "OK" : "OUT_OF_RANGE";
                case "secret" -> result = value == 1 ? "OK" : "MISSING_SECRET";
                default -> result = "UNKNOWN_KEY";
            }
            if (!result.equals("OK")) bad = true;
            System.out.println(key + " " + result);
        }
        System.out.println(!bad && seen.containsAll(List.of("timeout", "poolSize", "secret")) ? "START" : "CONFIG_ERROR");
    }
}

