import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int limit = sc.nextInt(), nonHeap = sc.nextInt(), margin = sc.nextInt(), heap = limit - nonHeap - margin;
        System.out.println(heap > 0 ? "HEAP " + heap : "HEAP INVALID");
        int n = sc.nextInt(), ready = 0;
        for (int k = 1; k <= n; k++) {
            String state = sc.next();
            int status = switch (state) {
                case "ready" -> 200;
                case "failed" -> 500;
                default -> 503;
            };
            if (state.equals("ready")) ready++;
            System.out.println(k + " " + state + " " + status);
        }
        System.out.println(ready > 0 ? "RECEIVED_TRAFFIC " + ready : "NO_TRAFFIC");
    }
}

