import java.util.*;

public class Main {
    static String rate(long total, long failed) {
        return String.format(Locale.ROOT, "%.2f%%",(total - failed) * 100.0 / total);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long budgetPerMille = sc.nextLong();
        int n = sc.nextInt();
        long sumTotal = 0, sumFailed = 0;
        boolean alert = false;
        for (int i = 0; i < n; i++) {
            String window = sc.next();
            long total = sc.nextLong(), failed = sc.nextLong();
            sumTotal += total;
            sumFailed += failed;
            if (total == 0) {
                System.out.println(window + " NO_DATA");
                continue;
            }
            boolean burn = failed * 1000 > total * budgetPerMille;
            if (burn) alert = true;
            System.out.println(window + " " + rate(total, failed) + " " + (burn ? "BURN" : "OK"));
        }
        System.out.println(sumTotal == 0 ? "TOTAL NO_DATA" : "TOTAL " + rate(sumTotal, sumFailed));
        System.out.println(alert ? "ALERT" : "HEALTHY");
    }
}
